DROP TABLE IF EXISTS `academic_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `academic_questions` (
  `question_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `course_id` bigint unsigned NOT NULL,
  `subject_id` bigint unsigned NOT NULL,
  `chapter_id` bigint unsigned NOT NULL,
  `question_type_id` bigint unsigned NOT NULL,
  `question_code` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `question_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `option_a` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `option_b` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `option_c` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `option_d` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `correct_option` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `difficulty` enum('Easy','Average','Difficult') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marks` int DEFAULT '1',
  `estimated_seconds` int DEFAULT '60',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`question_id`),
  UNIQUE KEY `question_code` (`question_code`),
  KEY `course_id` (`course_id`),
  KEY `subject_id` (`subject_id`),
  KEY `chapter_id` (`chapter_id`),
  KEY `question_type_id` (`question_type_id`),
  CONSTRAINT `academic_questions_ibfk_1` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `academic_questions_ibfk_2` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`subject_id`),
  CONSTRAINT `academic_questions_ibfk_3` FOREIGN KEY (`chapter_id`) REFERENCES `chapters` (`chapter_id`),
  CONSTRAINT `academic_questions_ibfk_4` FOREIGN KEY (`question_type_id`) REFERENCES `question_types` (`question_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
