--
-- Table structure for table `aptitude_questions`
--

DROP TABLE IF EXISTS `aptitude_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `aptitude_questions` (
  `aptitude_question_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `question_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `aptitude_slab` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '5-7',
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `topic` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `difficulty` enum('EASY','AVERAGE','DIFFICULT') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `option_a` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `option_b` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `option_c` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `option_d` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `correct_option` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `correct_answer_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `estimated_time_seconds` int unsigned NOT NULL,
  `marks` decimal(5,2) NOT NULL DEFAULT '1.00',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`aptitude_question_id`),
  UNIQUE KEY `uk_aptitude_question_code` (`question_code`),
  KEY `idx_aptitude_slab` (`aptitude_slab`),
  KEY `idx_aptitude_category` (`category`),
  KEY `idx_aptitude_topic` (`topic`),
  KEY `idx_aptitude_difficulty` (`difficulty`),
  CONSTRAINT `chk_aptitude_correct_option` CHECK ((`correct_option` in (_utf8mb4'A',_utf8mb4'B',_utf8mb4'C',_utf8mb4'D')))
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `aptitude_questions`
--

LOCK TABLES `aptitude_questions` WRITE;
/*!40000 ALTER TABLE `aptitude_questions` DISABLE KEYS */;
INSERT INTO `aptitude_questions` VALUES (61,'APT_5_7_001','5-7','Numerical Reasoning','Number Series','EASY','What number comes next: 2, 4, 6, 8, __?','9','10','11','12','B','10','The numbers increase by 2 each time.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(62,'APT_5_7_002','5-7','Numerical Reasoning','Number Series','EASY','What number is missing: 5, 10, 15, __, 25?','18','20','21','22','B','20','The sequence increases by 5.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(63,'APT_5_7_003','5-7','Numerical Reasoning','Place Value','EASY','What is the value of the digit 7 in 4,725?','7','70','700','7,000','C','700','The digit 7 is in the hundreds place.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(64,'APT_5_7_004','5-7','Numerical Reasoning','Divisibility','DIFFICULT','Which number is the smallest positive number that is divisible by both 6 and 8?','12','18','24','48','C','24','The least common multiple of 6 and 8 is 24.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(65,'APT_5_7_005','5-7','Numerical Reasoning','Number Relationship','AVERAGE','If 3 pencils cost ₹15, how much will 7 pencils cost at the same rate?','₹25','₹30','₹35','₹40','C','₹35','One pencil costs ₹5, so 7 pencils cost ₹35.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(66,'APT_5_7_006','5-7','Numerical Reasoning','Fractions','AVERAGE','Which fraction is the largest?','1/2','2/3','3/5','5/8','B','2/3','2/3 is about 0.67, larger than the other fractions.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(67,'APT_5_7_007','5-7','Numerical Reasoning','Arithmetic Reasoning','AVERAGE','A number is multiplied by 4 and then 6 is added. The result is 26. What is the number?','4','5','6','7','B','5','4 × 5 + 6 = 26.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(68,'APT_5_7_008','5-7','Numerical Reasoning','Percentage','DIFFICULT','A shirt costs ₹800. It is sold at a discount of 15%. What is the selling price?','₹660','₹680','₹700','₹720','B','₹680','15% of ₹800 is ₹120, so ₹800 − ₹120 = ₹680.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(69,'APT_5_7_009','5-7','Numerical Reasoning','Ratio','DIFFICULT','The ratio of boys to girls in a class is 3:2. If there are 25 students in total, how many are boys?','10','12','15','18','C','15','There are 5 equal parts; each part is 5 students. Boys = 3 × 5 = 15.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(70,'APT_5_7_010','5-7','Numerical Reasoning','Average','DIFFICULT','The average of 12, 15, 18 and one more number is 17. What is the missing number?','20','21','22','23','B','23','Total needed = 17 × 4 = 68. Known total = 45, so missing = 23.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(71,'APT_5_7_011','5-7','Logical Reasoning','Classification','EASY','Which one is different from the others?','Apple','Mango','Carrot','Banana','C','Carrot','Carrot is a vegetable; the others are fruits.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(72,'APT_5_7_012','5-7','Logical Reasoning','Analogy','EASY','Book is to Reading as Fork is to ___.','Writing','Eating','Drawing','Sleeping','B','Eating','A book is used for reading; a fork is used for eating.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(73,'APT_5_7_013','5-7','Logical Reasoning','Ordering','DIFFICULT','Four children P, Q, R and S have different heights. P is taller than Q. R is shorter than S but taller than Q. If S is shorter than P, who is definitely the tallest?','P','Q','R','S','A','P','The order is P > S > R > Q, so P is tallest.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(74,'APT_5_7_014','5-7','Logical Reasoning','Direction','EASY','You face north and turn right. Which direction are you facing?','West','East','South','North','B','East','A right turn from north points east.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(75,'APT_5_7_015','5-7','Logical Reasoning','Coding','AVERAGE','If CAT is coded as DBU by moving each letter one step forward, how is DOG coded?','EPH','EOG','DPH','FPH','A','EPH','D→E, O→P and G→H.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(76,'APT_5_7_016','5-7','Logical Reasoning','Seating Order','AVERAGE','Five children A, B, C, D and E stand in a line. A is before B, B is before C, and D is after C. Which must be true?','D is before A','A is before C','E is before A','C is before B','B','A is before C','A comes before B and B before C, so A must be before C.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(77,'APT_5_7_017','5-7','Logical Reasoning','Syllogism','AVERAGE','All roses are flowers. Some flowers are red. Which statement is definitely true?','All roses are red','Some roses are red','All roses are flowers','No roses are red','C','All roses are flowers','This follows directly from the first statement.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(78,'APT_5_7_018','5-7','Logical Reasoning','Age Reasoning','DIFFICULT','A father is 4 times as old as his son. Their total age is 50 years. How old is the son?','8','10','12','14','B','10','Let the son\'s age be x. Then 4x + x = 50, so x = 10.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(79,'APT_5_7_019','5-7','Logical Reasoning','Ordering','DIFFICULT','P is older than Q. R is younger than Q. S is older than P. Who is the oldest?','P','Q','R','S','D','S','S is older than P, which is older than Q, which is older than R.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(80,'APT_5_7_020','5-7','Logical Reasoning','Truth and Conditions','DIFFICULT','Three boxes are labeled Red, Blue and Green. Only one contains a prize. Red says \'The prize is not here.\' Blue says \'The prize is in Red.\' Green says \'Blue is lying.\' If only one statement is true, where is the prize?','Red box','Blue box','Green box','Cannot be determined','B','Blue box','If the prize is in Blue, Red is true, Blue is false, and Green is true—two statements. So not Blue. If in Red, Red is false, Blue true, Green false: exactly one true. Thus Red.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(81,'APT_5_7_021','5-7','Verbal Reasoning','Word Logic','DIFFICULT','If all \'Noras\' are \'Tels\' and no \'Tels\' are \'Vins\', which statement must be true?','Some Noras are Vins','No Noras are Vins','All Vins are Noras','Some Tels are Noras','B','No Noras are Vins','Noras are a subset of Tels, and Tels do not overlap with Vins.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(82,'APT_5_7_022','5-7','Verbal Reasoning','Antonym','EASY','Which word is opposite in meaning to \'ancient\'?','Old','Modern','Historic','Past','B','Modern','Modern is opposite in meaning to ancient.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(83,'APT_5_7_023','5-7','Verbal Reasoning','Analogy','EASY','Bird is to Nest as Bee is to ___.','Cave','Hive','Pond','Web','B','Hive','A nest is a bird\'s home; a hive is a bee\'s home.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(84,'APT_5_7_024','5-7','Verbal Reasoning','Word Classification','AVERAGE','Which word does not belong with the others?','Joyful','Happy','Cheerful','Angry','D','Angry','The first three describe happiness; angry does not.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(85,'APT_5_7_025','5-7','Verbal Reasoning','Word Relationship','AVERAGE','Choose the word that best completes the analogy: Hot : Cold :: Up : ___.','High','Down','Top','Over','B','Down','Hot and cold are opposites; up and down are opposites.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(86,'APT_5_7_026','5-7','Verbal Reasoning','Sentence Logic','AVERAGE','If all teachers in a school are adults, and Meena is a teacher, what must be true?','Meena is a student','Meena is an adult','Meena is a child','Meena is retired','B','Meena is an adult','Meena belongs to the group of teachers, all of whom are adults.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(87,'APT_5_7_027','5-7','Verbal Reasoning','Vocabulary','DIFFICULT','Which word can replace \'a person who is unable to read or write\' most accurately?','Scholar','Literate','Illiterate','Author','C','Illiterate','Illiterate means unable to read or write.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(88,'APT_5_7_028','5-7','Verbal Reasoning','Analogy','DIFFICULT','Thermometer is to Temperature as Clock is to ___.','Weight','Distance','Time','Speed','C','Time','A thermometer measures temperature; a clock measures time.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(89,'APT_5_7_029','5-7','Pattern Recognition','Number Pattern','EASY','Which number completes the pattern: 1, 3, 5, 7, __?','8','9','10','11','B','9','The pattern adds 2 each time.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(90,'APT_5_7_030','5-7','Pattern Recognition','Letter Pattern','EASY','Which letter comes next: A, C, E, G, __?','H','I','J','K','B','I','The pattern skips one letter each time.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(91,'APT_5_7_031','5-7','Pattern Recognition','Shape Pattern','EASY','A pattern repeats as circle, square, triangle, circle, square, triangle. What comes next?','Circle','Square','Triangle','Rectangle','A','Circle','The three-shape pattern repeats.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(92,'APT_5_7_032','5-7','Pattern Recognition','Number Pattern','EASY','What number comes next: 10, 20, 30, 40, __?','45','50','55','60','B','50','The pattern adds 10 each time.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(93,'APT_5_7_033','5-7','Pattern Recognition','Letter Pattern','AVERAGE','What comes next: AB, DE, GH, JK, __?','LM','MN','NO','OP','B','MN','Each pair advances by three letters: AB, DE, GH, JK, MN.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(94,'APT_5_7_034','5-7','Pattern Recognition','Mixed Pattern','AVERAGE','Which number replaces the question mark: 3, 6, 12, 24, ?','36','42','48','54','C','48','Each number is doubled.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(95,'APT_5_7_035','5-7','Pattern Recognition','Number Pattern','DIFFICULT','Find the missing number: 4, 7, 13, 25, 49, __?','73','85','97','101','C','97','The differences are +3, +6, +12, +24; next difference is +48, giving 97.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(96,'APT_5_7_036','5-7','Pattern Recognition','Mixed Pattern','DIFFICULT','What comes next: 2, 5, 11, 23, 47, __?','71','83','95','99','C','95','Each term is previous term ×2 +1.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(97,'APT_5_7_037','5-7','Spatial Reasoning','Directions','EASY','A boy walks 5 m east and then 5 m west. Where is he compared with his starting point?','5 m east','5 m west','At the starting point','10 m east','C','At the starting point','The two movements cancel each other.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(98,'APT_5_7_038','5-7','Spatial Reasoning','Directions','EASY','If you face south and turn left, which direction do you face?','East','West','North','South','A','East','A left turn from south points east.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(99,'APT_5_7_039','5-7','Spatial Reasoning','Shapes','EASY','Which shape has exactly three sides?','Circle','Square','Triangle','Rectangle','C','Triangle','A triangle has three sides.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(100,'APT_5_7_040','5-7','Spatial Reasoning','Position','AVERAGE','A is to the left of B. C is to the right of B. Which is in the middle?','A','B','C','Cannot say','B','B','The order is A, B, C.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(101,'APT_5_7_041','5-7','Spatial Reasoning','Directions','AVERAGE','Rina walks north, turns right, walks east, then turns right again. Which direction is she facing?','North','East','South','West','C','South','North → right = east → right = south.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(102,'APT_5_7_042','5-7','Spatial Reasoning','Cube Reasoning','AVERAGE','A cube has 6 faces. If one face is on the table, how many faces are not touching the table?','4','5','6','3','B','5','Only one face touches the table, leaving five faces not touching it.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(103,'APT_5_7_043','5-7','Spatial Reasoning','Position','DIFFICULT','Six students P, Q, R, S, T and U stand in a line. P is left of Q, R is right of Q, S is left of P, and T is right of R. Which student is definitely in the middle of these five ordered positions?','P','Q','R','S','B','Q','The order among S, P, Q, R, T is fixed, so Q is third.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(104,'APT_5_7_044','5-7','Spatial Reasoning','3D Visualization','DIFFICULT','A large cube is painted on all its outer faces and then cut into 8 equal smaller cubes. How many smaller cubes have paint on three faces?','2','4','6','8','D','8','Each corner cube has three painted faces, and all 8 smaller cubes are corners.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(105,'APT_5_7_045','5-7','Analytical Problem Solving','Age/Time','EASY','A train leaves at 9:00 AM and reaches at 11:00 AM. How long is the journey?','1 hour','2 hours','3 hours','4 hours','B','2 hours','11:00 AM − 9:00 AM = 2 hours.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(106,'APT_5_7_046','5-7','Analytical Problem Solving','Counting','EASY','There are 4 red balls and 3 blue balls in a box. How many balls are there altogether?','6','7','8','9','B','7','4 + 3 = 7.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(107,'APT_5_7_047','5-7','Analytical Problem Solving','Money','EASY','You have ₹50 and spend ₹18. How much money remains?','₹22','₹28','₹32','₹38','C','₹32','₹50 − ₹18 = ₹32.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(108,'APT_5_7_048','5-7','Analytical Problem Solving','Work Rate','AVERAGE','A machine makes 6 toys in 1 hour. At the same rate, how many toys will it make in 4 hours?','18','20','24','30','C','24','6 × 4 = 24.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(109,'APT_5_7_049','5-7','Analytical Problem Solving','Scheduling','AVERAGE','A class has three activities: Reading for 20 minutes, Maths for 30 minutes and Science for 25 minutes. How much time is needed in total?','65 minutes','70 minutes','75 minutes','80 minutes','C','75 minutes','20 + 30 + 25 = 75 minutes.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(110,'APT_5_7_050','5-7','Analytical Problem Solving','Comparison','AVERAGE','A shop has 48 apples. It packs them equally into 6 boxes. How many apples are in each box?','6','7','8','9','C','8','48 ÷ 6 = 8.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(111,'APT_5_7_051','5-7','Analytical Problem Solving','Multi-step','DIFFICULT','A student has ₹500. She buys a book for ₹185 and a bag for ₹225. How much money is left?','₹80','₹90','₹100','₹110','C','₹90','Total spent = ₹410; ₹500 − ₹410 = ₹90.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(112,'APT_5_7_052','5-7','Analytical Problem Solving','Logic Puzzle','DIFFICULT','A farmer has chickens and cows. There are 10 animals and 28 legs in total. How many cows are there?','2','4','6','8','B','4','If all 10 were chickens there would be 20 legs. The extra 8 legs require 4 cows instead of chickens.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(113,'APT_5_7_053','5-7','Analytical Problem Solving','Multi-step','DIFFICULT','A tank contains 240 litres. One quarter is used in the morning and then 30 litres are added. How many litres are in the tank now?','180','210','240','270','B','210','One quarter of 240 is 60; 240 − 60 + 30 = 210.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(114,'APT_5_7_054','5-7','Data Interpretation','Table Reading','EASY','Using the same data, how many books did Amit and Diya read together?','7','8','9','10','C','9','4 + 5 = 9.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(115,'APT_5_7_055','5-7','Data Interpretation','Bar Data','EASY','A shop sold 10 pens on Monday and 15 pens on Tuesday. How many more pens were sold on Tuesday?','3','5','10','25','B','5','15 − 10 = 5.',30,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(116,'APT_5_7_056','5-7','Data Interpretation','Comparison','AVERAGE','A survey shows favourite fruits: Apple 12, Mango 18, Banana 10, Orange 15. Which fruit is second most popular?','Apple','Mango','Banana','Orange','D','Orange','Mango is highest at 18; Orange is next at 15.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(117,'APT_5_7_057','5-7','Data Interpretation','Totals','AVERAGE','A student scored 18, 15, 17 and 20 in four tests. What is the total score?','60','65','70','75','C','70','18 + 15 + 17 + 20 = 70.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(118,'APT_5_7_058','5-7','Data Interpretation','Difference','AVERAGE','A library had 250 books. It received 75 new books and gave away 40 books. How many books does it have now?','275','285','295','305','C','285','250 + 75 − 40 = 285.',45,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(119,'APT_5_7_059','5-7','Data Interpretation','Percentage','DIFFICULT','In a survey of 100 students, 35 chose cricket, 25 chose football, 20 chose badminton and the rest chose basketball. How many chose basketball?','15','20','25','30','B','20','35 + 25 + 20 = 80, so 100 − 80 = 20.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48'),(120,'APT_5_7_060','5-7','Data Interpretation','Multi-step','DIFFICULT','A school collected ₹1,200 on Monday, ₹1,500 on Tuesday and ₹1,300 on Wednesday. It spent ₹2,000. How much money remained?','₹1,800','₹2,000','₹2,500','₹3,000','B','₹2,000','Total collected = ₹4,000; ₹4,000 − ₹2,000 = ₹2,000.',60,1.00,'2026-08-10 07:11:48','2026-08-10 07:11:48');
